// src/pages/Cursos.js
import React from "react";
import { Link } from "react-router-dom";

const cursos = [
  { id: 1, nombre: "Curso de React", precio: 100 },
  { id: 2, nombre: "Curso de Node.js", precio: 120 }
];

const Cursos = () => {
  return (
    <div>
      <h2>Lista de Cursos</h2>
      {cursos.map((curso) => (
        <div key={curso.id}>
          <h3>{curso.nombre}</h3>
          <p>Precio: ${curso.precio}</p>
          <Link to={`/curso/${curso.id}`}>
            <button>Ver más</button>
          </Link>
        </div>
      ))}
    </div>
  );
};

export default Cursos;
